files.content:
.combobox {
  position: relative;
  display: inline-block;
  min-inline-size: 14rem;
}

.combobox-field {
  position: relative;
  display: flex;
  align-items: center;
}
.combobox-input {
  inline-size: 100%;
  /* room for the caret on the trailing side */
  padding-inline-end: calc(var(--control-padding-x) + var(--icon-sm) + var(--space-2));
}
.combobox[data-size="sm"] .combobox-input { block-size: var(--control-height-sm); padding-inline-start: var(--space-3); padding-inline-end: calc(var(--space-3) + var(--icon-sm)); font-size: var(--font-sm); }
.combobox[data-size="lg"] .combobox-input { block-size: var(--control-height-lg); font-size: var(--control-font-size-lg); }
.combobox-caret {
  position: absolute;
  inset-inline-end: var(--control-padding-x);
  color: var(--icon-muted);
  pointer-events: none;
}

.combobox-list {
  position: absolute;
  z-index: var(--z-dropdown);
  inset-block-start: calc(100% + var(--space-1));
  inset-inline: 0;
  margin: 0;
  padding: var(--space-1);
  list-style: none;
  max-block-size: 16rem;
  overflow-y: auto;
  background: var(--popover);
  /* Its own popover surface, so it answers for what a row hovers to. */
  --surface-hover: var(--popover-hover);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-popover);
}

.combobox-option {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  min-block-size: var(--control-height);
  padding-inline: var(--space-3);
  border-radius: var(--radius-md);
  font-size: var(--control-font-size);
  color: var(--popover-foreground);
  cursor: pointer;
}
/* Keyboard-active OR hovered option: one highlight, driven by data-active. The
   rule that paints it is further down, with the reason. */
/* Pressed: one stop past hover, the third answer every control now gives. */
.combobox-option:active { background: var(--accent-soft); }
.combobox-option[aria-selected="true"] {
  font-weight: var(--font-weight-medium);
  color: var(--primary-accent);
}

.combobox-empty {
  padding: var(--space-2) var(--space-3);
  font-size: var(--font-sm);
  color: var(--muted-foreground);
}

/* Multi-select: tags sit inline before the input; the field wraps.
 *
 * A MULTI-SELECT IS STILL ONE FIELD. The input gives up its border below so the
 * tags, the text and the caret read as one line — which left the control with
 * no box at all: on a card the chips floated on the surface and nothing said
 * where the field began or ended, and focus landed on a borderless input with
 * no ring around the thing the reader is typing into (2026-08-29). The frame
 * moves to the wrapper that is now the field, keeping the recipe in Input.css:
 * 1px --input on --background at --control-radius, hover to --ring, a ring on
 * focus, and the resting border dropped on a muted ground. */
.combobox[data-multiple] .combobox-field {
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-1);
  min-block-size: var(--control-height);
  block-size: auto;
  padding: var(--space-1) var(--space-2);
  border-radius: var(--control-radius);
  border: 1px solid var(--input);
  background: var(--background);
  transition: border-color var(--duration-fast);
}
.combobox[data-multiple] .combobox-field:hover { border-color: var(--ring); }
.combobox[data-multiple][data-surface="muted"] .combobox-field,
.combobox[data-multiple][data-surface="muted"] .combobox-field:hover { border-color: transparent; }
.combobox[data-multiple] .combobox-field:focus-within {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
}
/* The input inside no longer draws its own ring — the field around it does, and
   two rings on one control is two controls. */
.combobox[data-multiple] .combobox-input:focus-visible { outline: none; }
.combobox[data-multiple] .combobox-input {
  flex: 1;
  min-inline-size: 6rem;
  inline-size: auto;
  border: none;
  padding: 0;
  block-size: auto;
}
.combobox-check {
  margin-inline-start: auto;
  color: var(--primary-accent);
}

/* THE ROW ENTER WILL LAND ON, AND IT IS A SOLID ROW — not a rail.
 *
 * This drew a brand-coloured bar down the leading edge. The owner asked three
 * times for it to go (2026-08-29), and simply deleting it was not an option:
 * this list keeps focus on the field and names the row through
 * `aria-activedescendant`, so the row's mark IS the focus indicator, and the
 * tint underneath measures 1.15:1 where SC 2.4.11 asks 3:1.
 *
 * So the mark changed rather than disappeared. A solid `--primary` row with its
 * own foreground measures 7.59:1 against the popover — the same number the
 * focus ring carries everywhere else in this system, which is the point: it is
 * not a weaker answer wearing a different shape, it is the strongest mark the
 * system has, and it is neither a border nor a ring on a row that is not
 * focused. It is also what a menu highlight looks like on every desktop the
 * reader already uses. */
.combobox-option[data-active] {
  background: var(--primary);
  color: var(--primary-foreground);
}
.combobox-option[data-active] .combobox-check { color: var(--primary-foreground); }

import './Combobox.css'
import { useId, useRef, useState, type KeyboardEvent } from 'react'
import { cn } from '../lib/cn'
import { type Option } from '../lib/option'
import { Icon } from '../Icon'
import { Chip } from '../Chip'

/** A Combobox choice. Nothing beyond the shared <Option>: this control renders
 *  a label and filters on it, and any field it does not draw would be a lie. */
export type ComboboxOption<V extends string> = Option<V>

type Props<V extends string> = {
  options: readonly ComboboxOption<V>[]
  /** Accessible name for the text field. */
  label: string
  /** Multi-select: `value` is an array and picks render as removable tags.
   *  Single (default): `value` is one option value. */
  multiple?: boolean
  /** One value in single mode, an array in multi mode. */
  value?: V | readonly V[]
  /** Receives one value in single mode, the full array in multi mode. Pass the
   *  handler that matches your `multiple` setting. */
  onChange: ((next: V) => void) | ((next: V[]) => void)
  placeholder?: string
  className?: string
  /** Matched against the option label, case-insensitive, by default. Pass a
   *  custom matcher to search other fields or fuzzy-match. */
  filter?: (option: ComboboxOption<V>, query: string) => boolean
  /** Shown when the query matches nothing. Default "No matches". */
  emptyLabel?: string
  /** sm / md (default) / lg — matches the shared control height/padding scale. */
  size?: 'sm' | 'md' | 'lg'
  /** Which surface the field sits on. On `muted` (a page/PageHeader) the border
   *  is dropped since the white fill separates it; `base` (default, a white card
   *  or form) keeps the border. Invalid + focus stay visible on both. */
  surface?: 'base' | 'muted'
}

const defaultFilter = <V extends string>(o: ComboboxOption<V>, q: string) =>
  o.label.toLowerCase().includes(q.trim().toLowerCase())

/* The listbox renders inline below the field rather than portaled: a filter box
 * is short-lived and scoped to its container. */

/** Searchable select — the ARIA combobox pattern (input + listbox), for when a
 *  plain <Select> has too many options to scan. Type to filter, Arrow keys to
 *  move, Enter to pick, Escape to close. `multiple` turns it into a token input
 *  where picks render as removable <Chip>s and the list stays open. 
 *
 * Copy: the empty label says what was searched for and offers the way out — "No
 * supplier matches 'nortwind'. Check the spelling, or add a supplier." A
 * bare "No results" leaves the reader stuck on their own typo.
 */
export function Combobox<V extends string>(props: Props<V>) {
  const { options, label, placeholder, className, filter = defaultFilter, emptyLabel = 'No matches', surface = 'base', size } = props
  const multiple = props.multiple === true
  /* The prop types are collapsed to one shape so the registry can read them;
   * `multiple` is the runtime discriminant, so value/onChange are narrowed by
   * cast here (the public API still matches the handler you pass). */
  const singleValue = props.value as V | undefined
  const selectedValues = multiple ? ((props.value as readonly V[] | undefined) ?? []) : []
  const onChangeSingle = props.onChange as (next: V) => void
  const onChangeMulti = props.onChange as (next: V[]) => void

  const [query, setQuery] = useState('')
  const [open, setOpen] = useState(false)
  const [active, setActive] = useState(0)
  const listId = useId()
  const optionId = (i: number) => `${listId}-opt-${i}`
  const wrapRef = useRef<HTMLDivElement>(null)

  const isSelected = (v: V) => (multiple ? selectedValues.includes(v) : singleValue === v)
  const singleLabel = !multiple ? options.find((o) => o.value === singleValue)?.label ?? '' : ''
  /* Single: show the picked label while closed, the query while typing.
   * Multi: the input is always just the query (picks are shown as tags). */
  const shown = multiple ? query : open ? query : singleLabel
  const matches = open ? options.filter((o) => filter(o, query)) : options

  const pick = (opt: ComboboxOption<V>) => {
    if (multiple) {
      const next = selectedValues.includes(opt.value)
        ? selectedValues.filter((v) => v !== opt.value)
        : [...selectedValues, opt.value]
      onChangeMulti(next)
      setQuery('')
      /* stay open so several can be picked in a row */
    } else {
      onChangeSingle(opt.value)
      setQuery('')
      setOpen(false)
    }
  }

  const removeTag = (v: V) => {
    if (multiple) onChangeMulti(selectedValues.filter((x) => x !== v))
  }

  const onKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault()
      if (!open) { setOpen(true); return }
      setActive((i) => Math.min(i + 1, matches.length - 1))
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      setActive((i) => Math.max(i - 1, 0))
    } else if (e.key === 'Enter') {
      if (open && matches[active]) { e.preventDefault(); pick(matches[active]) }
    } else if (e.key === 'Escape') {
      setOpen(false)
      setQuery('')
    } else if (e.key === 'Backspace' && multiple && query === '' && selectedValues.length) {
      /* Backspace on an empty field removes the last token, like a tag input. */
      removeTag(selectedValues[selectedValues.length - 1])
    }
  }

  const tags = multiple
    ? selectedValues.map((v) => ({ value: v, label: options.find((o) => o.value === v)?.label ?? v }))
    : []

  return (
    <div
      ref={wrapRef}
      className={cn('combobox', className)}
      data-multiple={multiple || undefined}
      data-size={size}
      /* The multi-select's field frame is the WRAPPER, not the input, so the
         surface has to be readable from the root as well. */
      data-surface={surface}
      onBlur={(e) => {
        if (!wrapRef.current?.contains(e.relatedTarget as Node)) {
          setOpen(false)
          setQuery('')
        }
      }}
    >
      <div className="combobox-field">
        {tags.map((t) => (
          <Chip key={t.value} size="sm" onRemove={() => removeTag(t.value)} removeLabel={`Remove ${t.label}`}>
            {t.label}
          </Chip>
        ))}
        <input
          className="input combobox-input"
          data-surface={surface}
          role="combobox"
          aria-expanded={open}
          aria-controls={listId}
          aria-autocomplete="list"
          aria-activedescendant={open && matches[active] ? optionId(active) : undefined}
          aria-label={label}
          placeholder={multiple && tags.length ? undefined : placeholder}
          value={shown}
          onChange={(e) => { setQuery(e.target.value); setOpen(true); setActive(0) }}
          onFocus={() => setOpen(true)}
          /* Reopen on click too: after a single-select pick the input keeps
             focus, so onFocus won't fire again and only a click can reopen the
             list (without this you had to blur and refocus). */
          onClick={() => setOpen(true)}
          onKeyDown={onKeyDown}
        />
        <Icon name="arrow_drop_down" className="combobox-caret" />
      </div>

      {open && (
        <ul className="combobox-list" role="listbox" id={listId} aria-label={label} aria-multiselectable={multiple || undefined}>
          {matches.length === 0 && <li className="combobox-empty" role="presentation">{emptyLabel}</li>}
          {matches.map((opt, i) => (
            <li
              key={opt.value}
              id={optionId(i)}
              role="option"
              aria-selected={isSelected(opt.value)}
              className="combobox-option"
              data-active={i === active || undefined}
              /* mousedown, not click: fires before the input's blur so the
                 selection lands instead of the list closing first. */
              onMouseDown={(e) => { e.preventDefault(); pick(opt) }}
              onMouseEnter={() => setActive(i)}
            >
              {opt.label}
              {multiple && isSelected(opt.value) && <Icon name="check" className="combobox-check" />}
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}
